// Private, expiring draft recovery. Raw upload photos stay on this device only.
(()=>{
 const fields=['names','second-name','personal-details','own-idea','email','recipient-name','address-line1','address-line2','town','postcode','dedication'];
 let db,ready=false,timer,remoteId=null,remoteKey=null;
 const status=document.querySelector('#draft-status');
 const open=new Promise((resolve,reject)=>{const r=indexedDB.open('cq-private-draft',1);r.onupgradeneeded=()=>r.result.createObjectStore('drafts');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});
 async function access(mode,fn){db=await open;return new Promise((resolve,reject)=>{const tx=db.transaction('drafts',mode),r=fn(tx.objectStore('drafts'));r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
 function snapshot(){const values={};for(const id of fields)values[id]=document.getElementById(id).value;return {expires:Date.now()+7*86400000,values,state:{...state},ideaOffset,second:!$('#second-person').hidden,permission:$('#photo-permission').checked,face:$('#face-confirm').checked,orderRequest,remoteId,remoteKey};}
 async function save(){if(!ready)return;try{$('#forget-draft').hidden=false;await access('readwrite',s=>s.put(snapshot(),'current'));status.textContent='Draft saved on this device for 7 days. Use Start fresh to remove it.';}catch{status.textContent='This browser cannot save your draft. Keep this tab open, or email a return link after your preview.';}}
 async function restore(d){if(!d||d.expires<Date.now())return;for(const id of fields)if(typeof d.values?.[id]==='string')document.getElementById(id).value=d.values[id];Object.assign(state,d.state);if(!d.state.storyMode)state.storyMode=d.state.mood==='own'?'plot':'invent';if(state.mood==='own')state.mood='adventure';ideaOffset=Number.isInteger(d.ideaOffset)?d.ideaOffset:0;remoteId=d.remoteId;remoteKey=d.remoteKey;orderRequest=d.orderRequest||null;$('#second-person').hidden=!d.second;$('#photos').multiple=!!d.second;$('#photo-permission').checked=!!d.permission;$('#face-confirm').checked=!!d.face;for(const name of ['age','mood','product','story-mode'])for(const radio of $$(`input[name="${name}"]`))radio.checked=radio.value===(name==='story-mode'?state.storyMode:state[name]);buildIdeas();updateLive();if(!d.state.storyMode&&state.storyDraft&&d.state.mood==='own'){try{const old=JSON.parse(d.state.storyBasis);if(old.idea===d.values['own-idea']&&old.names===state.names&&old.age===state.age)state.storyBasis=storyBasis();}catch{}}updateProduct();if(state.storyDraft)renderStoryDraft();if(state.characterImages.length){$('#preview-image').src=state.characterImages[0];$('#result-story-title').textContent=state.storyDraft.title;$('#story-copy').textContent=state.storyDraft.spreads[0].text;$('#making-state').hidden=true;$('#result-state').hidden=false;$('#choose-book').disabled=false;if(state.characterImages[1]){$('#preview-image-second').src=state.characterImages[1];$('#preview-image-second').hidden=false;$('#preview-art').classList.add('two-people');}showStep(5);}else{showStep([1,8,9,12].includes(state.step)?state.step:state.photos.length?([2,3,4,10].includes(state.step)?state.step:4):2);if(state.photos.length){$('#face-confirm-wrap').hidden=false;$('#photo-check').hidden=false;$('#photo-check').textContent='Your previously checked photos are saved on this device.';$('#photo-check').classList.add('pass');}}$('#resume-draft').hidden=true;status.textContent='Your draft is restored.';updateCover();}
 window.cqSaveDraft=save;window.addEventListener('pagehide',()=>void save());
 document.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(save,650);});document.addEventListener('change',()=>{clearTimeout(timer);timer=setTimeout(save,650);});window.addEventListener('cq-draft-change',()=>void save());
 $('#forget-draft').onclick=async()=>{await access('readwrite',s=>s.delete('current'));location.assign('/create');};
 $('#email-draft').onclick=async()=>{const button=$('#email-draft'),note=$('#draft-email-status');button.disabled=true;try{remoteId=remoteId||crypto.randomUUID();remoteKey=remoteKey||crypto.randomUUID()+crypto.randomUUID();const d=snapshot();d.state.photos=[];d.state.photoChecks=[];d.orderRequest=null;d.remoteId=remoteId;d.remoteKey=remoteKey;for(const id of ['recipient-name','address-line1','address-line2','town','postcode'])d.values[id]='';const r=await fetch('/api/orders/drafts/'+remoteId,{method:'PUT',headers:{'Content-Type':'application/json',Authorization:'Bearer '+remoteKey},body:JSON.stringify({draft:d,previewId:state.previewId,email:$('#email').value.trim()}),signal:AbortSignal.timeout(30000)});const result=await r.json();if(!r.ok)throw Error(result.error||'Could not save your return link.');note.textContent=result.sent?'Private return link sent. It expires in 7 days.':'Your draft is saved, but the email failed. Please try again.';await save();}catch(e){note.textContent=e.message;}finally{button.disabled=false;}};
 (async()=>{try{const params=new URLSearchParams(location.hash.slice(1)),id=params.get('draft'),key=params.get('key');if(id&&key){const r=await fetch('/api/orders/drafts/'+encodeURIComponent(id),{headers:{Authorization:'Bearer '+key}});const d=await r.json();if(!r.ok)throw Error(d.error||'This draft link is unavailable.');await restore(d);ready=true;await save();history.replaceState(null,'',location.pathname+location.search);}else{const d=await access('readonly',s=>s.get('current'));if(d&&d.expires>Date.now()){await restore(d);ready=true;await save();return;}else if(d)await access('readwrite',s=>s.delete('current'));ready=true;}}catch(e){status.textContent=e.message||'Draft recovery is unavailable. You can still create a book.';ready=true;}})();
})();
